B={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
O={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# transform points in 9x10 rectangle dihedral, normalize bounding rectangle output dims as needed
transforms=[]
for k in range(4):
    def rot(p):
        r,c=p
        return c,8-r # clockwise 90 for 9x10
    X=set(B)
    for _ in range(k): X={rot(p) for p in X}
    transforms.append((f'rot{k*90}',X))
    # mirror horizontal over width 10 on source then rotate
    Y={(r,9-c) for r,c in X} # this is post-transform mirror wrong but dims adjusted
    transforms.append((f'rot{k*90} + mirror output',Y))
for n,X in transforms:
    minr=min(r for r,c in X); minc=min(c for r,c in X)
    X={(r-minr,c-minc) for r,c in X}
    print(n, X==O, len(X&O), sorted(X))

minr=min(r for r,c in O); minc=min(c for r,c in O); On={(r-minr,c-minc) for r,c in O}
for n,X in transforms:
    minr=min(r for r,c in X); minc=min(c for r,c in X); Xn={(r-minr,c-minc) for r,c in X}
    print(n,Xn==On,len(Xn&On),len(Xn^On))
